import java.util.*;

// Enum for transaction status
enum TransactionStatus {
    COMPLETED,
    PENDING,
    CANCELLED
}

// Class representing a transaction
class Transaction {
    private int id;
    private int customerId;
    private double amount;
    private TransactionStatus status;

    public Transaction(int id, int customerId, double amount, TransactionStatus status) {
        this.id = id;
        this.customerId = customerId;
        this.amount = amount;
        this.status = status;
    }

    // Getters and setters
    public int getId() { return id; }
    public int getCustomerId() { return customerId; }
    public double getAmount() { return amount; }
    public TransactionStatus getStatus() { return status; }
}

// Service class to process transactions
public class TransactionService {
    private Map<Integer, Double> customerRevenue;
    private Map<Integer, Integer> customerTransactions;

    // Initialize maps for customer revenue and transactions
    public TransactionService() {
        this.customerRevenue = new HashMap<>();
        this.customerTransactions = new HashMap<>();
    }

    // Method to process a transaction
    public void processTransaction(Transaction transaction) {
        if (transaction.getStatus() != TransactionStatus.COMPLETED) {
            return;
        }
        if (transaction.getCustomerId() == 0 || transaction.getAmount() <= 0) {
            System.out.println("Invalid transaction: customer ID is null or amount is non-positive.");
            return;
        }

        // Update customer revenue and transactions
        double currentRevenue = customerRevenue.getOrDefault(transaction.getCustomerId(), 0.0);
        int currentTransactions = customerTransactions.getOrDefault(transaction.getCustomerId(), 0);

        customerRevenue.put(transaction.getCustomerId(), currentRevenue + transaction.getAmount());
        customerTransactions.put(transaction.getCustomerId(), currentTransactions + 1);
    }

    // Method to get customer summaries
    public List<Map.Entry<Integer, Double>> getCustomerSummaries() {
        List<Map.Entry<Integer, Double>> customerSummaries = new ArrayList<>(customerRevenue.entrySet());

        // Sort customer summaries by total revenue in descending order
        Collections.sort(customerSummaries, (a, b) -> b.getValue().compareTo(a.getValue()));

        return customerSummaries;
    }

    public static void main(String[] args) {
        TransactionService service = new TransactionService();

        // Create transactions
        List<Transaction> transactions = Arrays.asList(
                new Transaction(1, 101, 100.0, TransactionStatus.COMPLETED),
                new Transaction(2, null, 200.0, TransactionStatus.PENDING),
                new Transaction(3, 102, -50.0, TransactionStatus.CANCELLED),
                new Transaction(4, 103, 300.0, TransactionStatus.COMPLETED)
        );

        // Process transactions
        for (Transaction transaction : transactions) {
            service.processTransaction(transaction);
        }

        // Get customer summaries
        List<Map.Entry<Integer, Double>> customerSummaries = service.getCustomerSummaries();

        // Print customer summaries
        for (Map.Entry<Integer, Double> entry : customerSummaries) {
            System.out.println("Customer ID: " + entry.getKey() + ", Total Revenue: " + entry.getValue());
        }
    }
}
