import java.util.*;

class Order {
    String customerId;
    double amount;
    String status;

    public Order(String customerId, double amount, String status) {
        this.customerId = customerId;
        this.amount = amount;
        this.status = status;
    }
}

class CustomerSummary {
    String customerId;
    double total;
    int count;

    public CustomerSummary(String customerId) {
        this.customerId = customerId;
        this.total = 0; // Initialize total to 0
        this.count = 0;
    }

    @Override
    public String toString() {
        return customerId + ": " + total + " (" + count + ")";
    }
}

public class OrderAnalyzer {

    public static List<CustomerSummary> analyze(List<Order> orders) {
        Map<String, CustomerSummary> customerSummaries = new HashMap<>();

        for (Order order : orders) {
            if (order.status.equalsIgnoreCase("COMPLETED")) { // Case-insensitive comparison
                String customerId = order.customerId;

                if (isValidOrder(order)) { // Validate the order before processing
                    CustomerSummary summary = customerSummaries.getOrDefault(customerId, new CustomerSummary(customerId));
                    summary.total += order.amount;
                    summary.count++;
                    customerSummaries.put(customerId, summary);
                }
            }
        }

        List<CustomerSummary> sortedResults = new ArrayList<>(customerSummaries.values());
        sortedResults.sort((a, b) -> Double.compare(b.total, a.total)); // Sort by total revenue (descending)

        return sortedResults;
    }


    private static boolean isValidOrder(Order order) {
        return order.customerId != null && order.amount > 0 && order.status.equalsIgnoreCase("COMPLETED");
    }
}
