```java
class TransactionService {
    /**
     * Processes a list of transactions and returns customer summaries.
     *
     * @param transactions List of transactions to process
     * @return Sorted list of CustomerSummary objects by total revenue (descending)
     */
    public List<CustomerSummary> getCustomerSummaries(List<Transaction> transactions) {
        // Step 1: Filter out non-completed transactions
        List<Transaction> completedTransactions = transactions.stream()
                .filter(t -> t.getStatus() == TransactionStatus.COMPLETED)
                .collect(Collectors.toList());

        // Step 2: Reject invalid transactions (null customerId or non-positive amount)
        List<Transaction> validCompletedTransactions = completedTransactions.stream()
                .filter(t -> t.getCustomerId() != null && t.getAmount() > 0)
                .collect(Collectors.toList());

        // Step 3: Group by customer ID and calculate total revenue & count
        Map<String, CustomerSummary> customerSummariesMap = validCompletedTransactions.stream()
                .collect(Collectors.groupingBy(
                        Transaction::getCustomerId,
                        Collectors.teeing(
                                // Sum the amount for each customer
                                Collectors.reducing(0.0, Transaction::getAmount, Double::sum),
                                // Count the number of transactions per customer
                                Collectors.counting(),
                                (totalRevenue, count) -> new CustomerSummary(
                                        null,
                                        totalRevenue,
                                        count.intValue()
                                )
                        )
                ));

        // Step 4: Convert map to list and sort by total revenue descending
        List<CustomerSummary> customerSummaries = new ArrayList<>(customerSummariesMap.values());
        customerSummaries.sort((a, b) -> Double.compare(b.getTotalRevenue(), a.getTotalRevenue()));

        return customerSummaries;
    }
}
